import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, CheckCircle, CreditCard } from 'lucide-react';
import { useTranslation } from '../i18n/translations';

export default function PaymentModal({ isOpen, onClose, item, type }) {
  const { t } = useTranslation();
  const [success, setSuccess] = useState(false);

  if (!isOpen || !item) return null;

  const basePrice = type === 'stay' ? item.price_per_night : 300; // Mock pass fee
  const commission = type === 'stay' ? Math.floor(basePrice * 0.05) : 50;
  const total = basePrice + commission;

  const handlePay = () => {
    setSuccess(true);
    setTimeout(() => {
      setSuccess(false);
      onClose();
    }, 3000);
  };

  return (
    <AnimatePresence>
      <div style={{
        position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, 
        background: 'rgba(0,0,0,0.5)', backdropFilter: 'blur(4px)',
        display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000
      }}>
        <motion.div 
          initial={{ y: 50, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          exit={{ y: 50, opacity: 0 }}
          style={{
            background: 'white', borderRadius: '24px', width: '90%', maxWidth: '400px',
            padding: '24px', boxShadow: '0 25px 50px -12px rgba(0,0,0,0.25)',
            position: 'relative'
          }}
        >
          <button onClick={onClose} style={{ position: 'absolute', top: '16px', right: '16px', background: 'none', border: 'none', cursor: 'pointer', color: '#64748b' }}>
            <X size={24} />
          </button>

          {!success ? (
            <>
              <h2 style={{ margin: '0 0 16px', color: '#0f172a', display: 'flex', alignItems: 'center', gap: '8px' }}>
                <CreditCard /> {t('paymentTitle')}
              </h2>
              <div style={{ background: '#f8fafc', padding: '16px', borderRadius: '12px', marginBottom: '20px' }}>
                <h3 style={{ margin: '0 0 8px', color: '#334155' }}>{item.name}</h3>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px', color: '#64748b' }}>
                  <span>{t('baseFee')}</span>
                  <span>₹{basePrice}</span>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '12px', color: '#64748b', borderBottom: '1px solid #e2e8f0', paddingBottom: '12px' }}>
                  <span>{t('commission')}</span>
                  <span>₹{commission}</span>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', fontWeight: 'bold', color: '#0f172a', fontSize: '18px' }}>
                  <span>{t('total')}</span>
                  <span>₹{total}</span>
                </div>
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                <button onClick={handlePay} style={{ background: '#0284c7', color: 'white', border: 'none', padding: '12px', borderRadius: '12px', fontWeight: 'bold', cursor: 'pointer', fontSize: '16px', display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '8px' }}>
                  {t('payWith')} UPI (GPay/PhonePe)
                </button>
                <button onClick={handlePay} style={{ background: '#cbd5e1', color: '#334155', border: 'none', padding: '12px', borderRadius: '12px', fontWeight: 'bold', cursor: 'pointer', fontSize: '16px' }}>
                  {t('payWith')} Card
                </button>
              </div>
            </>
          ) : (
            <motion.div 
              initial={{ scale: 0.8, opacity: 0 }} 
              animate={{ scale: 1, opacity: 1 }} 
              style={{ textAlign: 'center', padding: '24px 0' }}
            >
              <CheckCircle size={64} color="#10b981" style={{ margin: '0 auto 16px' }} />
              <h3 style={{ color: '#10b981', margin: 0 }}>{t('successMsg')}</h3>
              <div style={{ marginTop: '20px', background: '#f1f5f9', padding: '16px', borderRadius: '12px' }}>
                <img src={`https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=RAHBAR_${item.id}_${Date.now()}`} alt="QR Code" style={{ borderRadius: '8px' }} />
                <p style={{ margin: '12px 0 0', fontWeight: 'bold', color: '#334155' }}>ID: RAHBAR_{item.id}_{Date.now().toString().slice(-4)}</p>
              </div>
            </motion.div>
          )}
        </motion.div>
      </div>
    </AnimatePresence>
  );
}
